// POST /integrations/okta/events  — SCIM/user lifecycle webhook
export async function handleWebhook(req: Request): Promise<Response> {
  const raw = await req.text()
  const sig = req.headers.get('x-okta-signature') ?? ''

  // 1. Reject unsigned/forged events at the boundary — never trust external input.
  if (!verifyHmac(raw, sig, process.env.OKTA_WEBHOOK_SECRET!)) {
    await audit.log('webhook.rejected', { reason: 'bad_signature' })
    return new Response('invalid signature', { status: 401 })
  }

  const event = JSON.parse(raw) as LifecycleEvent

  // 2. Idempotency: the sender may retry — the same event must not double-apply.
  if (await seen(event.id)) return new Response('ok', { status: 200 })

  // 3. Durable enqueue BEFORE acking. If we crash after 200, the event is gone.
  await queue.enqueue('user-sync', event)
  await markSeen(event.id)
  await audit.log('webhook.accepted', { eventId: event.id, actor: event.target })

  // 4. Ack only after it is safely persisted.
  return new Response('ok', { status: 200 })
}

// The reconciler is the SOURCE OF TRUTH, not the webhook. Runs on a schedule
// so a dropped event self-heals: diff IdP roles against downstream, replay gaps.
export async function reconcile(): Promise<Drift[]> {
  const truth = await idp.listAssignments()   // source of truth
  const live = await saas.listAssignments()    // what downstream actually has
  const drift = diffAssignments(truth, live)   // RBAC matrix diff
  for (const d of drift) await queue.enqueue('user-sync', toEvent(d))
  await audit.log('reconcile.run', { driftCount: drift.length })
  return drift
}

